client_script:
// Web Form Client Script for "Correspondence Request"
frappe.ready(function() {
    console.log("ddddddddddddd");
    // Only run if the form is for a new document (no name)
    if (!frappe.web_form.doc.name) {
        // Set 'sender' to current logged-in user
        frappe.web_form.set_value('sender', frappe.session.user);
    }
});

frappe.web_form.after_save = function() {
    // Check if this was a new submission (not an edit)
    if (!frappe.web_form.original_doc) {
        const mediaType = frappe.web_form.get_value('media_type')?.toString().trim();
        console.log(mediaType)
        // Redirect to special form for 'foreign media'
        if (mediaType && mediaType === 'Foreign Journalist') {
            // Small delay to ensure success message shows
            frappe.msgprint(__('Thank you! Redirecting to Foreign Media Request Form...'));
            setTimeout(() => {
                window.location.href = '/media-request/new';
            }, 800);
        } 
        // Normal submission flow
        else {
            const docname = frappe.web_form.doc.name;
            const redirectUrl = '/press/my-profile/new';

            frappe.msgprint(__('Thank You for applying!'));
            setTimeout(() => {
                window.location.href = redirectUrl;
            }, 800);
        }
    }
};

frappe.web_form.onload = () => {
    const params = new URLSearchParams(window.location.search);

    // Example: set 'media_type' from ?media_type=...
    const mediaType = params.get('media_type');
    console.log(mediaType)
    if (mediaType) {
        frappe.web_form.set_value('media_type', mediaType);
        frappe.web_form.refresh_field('media_type'); // ensures UI updates
    }

    // Add more fields as needed:
    // const region = params.get('region');
    // if (region) frappe.web_form.set_value('region', region);
};

