(function () {
  // ===============================
  // CONFIG
  // ===============================
  const CFG = {
    URL_PARAM: "job_title",
    JOB_FIELD: "job_title",
    API_METHOD: "get_dynamic_job_fields",
    JSON_FIELDNAME: "custom_dynamic_answers_json_wf",
    SEARCH_FIELDNAME: "custom_answers_search_index", // ✅ حقل الفهرسة للبحث
    SECTION_CLASS: "dynamic-form-section",
  };

  let PATCHED = false;

  // ===============================
  // 1️⃣ بعد تحميل الصفحة
  // ===============================
  frappe.web_form.after_load = function () {
    patch_get_values_once();
    const urlParams = new URLSearchParams(window.location.search);
    const jobOpening = urlParams.get(CFG.URL_PARAM);
    if (jobOpening) {
      frappe.web_form.set_value(CFG.JOB_FIELD, jobOpening);
    }
  };

  // ===============================
  // 2️⃣ عند تغيير job_title
  // ===============================
  frappe.web_form.on(CFG.JOB_FIELD, function (field, value) {
    if (!value) { removeDynamicSection(); return; }
    frappe.call({
      method: CFG.API_METHOD,
      args: { job_opening: value },
      callback: function (r) {
        if (r.message && r.message.fields && r.message.fields.length) {
          renderFields(r.message.fields);
        } else { removeDynamicSection(); }
      },
      error: function () { removeDynamicSection(); }
    });
  });

  // ===============================
  // 3️⃣ حذف القسم الديناميكي
  // ===============================
  function removeDynamicSection() {
    document.querySelectorAll("." + CFG.SECTION_CLASS).forEach((el) => el.remove());
  }

  // ===============================
  // 4️⃣ بناء الحقول الديناميكية
  // ===============================
  function renderFields(fields) {
    const formWrapper = document.querySelector(".web-form-wrapper");
    if (!formWrapper) return;
    removeDynamicSection();

    const sectionWrapper = document.createElement("div");
    sectionWrapper.className = CFG.SECTION_CLASS;
    sectionWrapper.style.cssText = "margin-top: 30px; padding-top: 20px; border-top: 1px solid #e3e3e3;";

    const sectionTitle = document.createElement("h4");
    sectionTitle.textContent = "معلومات إضافية";
    sectionTitle.style.cssText = "margin-bottom: 20px; font-size: 15px; font-weight: 600;";
    sectionWrapper.appendChild(sectionTitle);

    fields.forEach(function (field) {
      const formGroup = document.createElement("div");
      formGroup.className = "form-group";
      formGroup.style.marginBottom = "18px";

      const isRequired = field.reqd === 1 || field.reqd === true || field.mandatory === 1 || field.mandatory === true;
      const label = document.createElement("label");
      label.innerHTML = (field.label || "") + (isRequired ? ' <span style="color:red">*</span>' : "");

      let input;

      if (field.type === "Select" || field.fieldtype === "Select") {
        input = document.createElement("select");
        input.className = "form-control";
        const defaultOpt = document.createElement("option");
        defaultOpt.value = ""; defaultOpt.textContent = "-- اختر --";
        input.appendChild(defaultOpt);
        if (field.options) {
          String(field.options).trim().split(/\n/).forEach(function (opt) {
            opt = (opt || "").trim(); if (!opt) return;
            const optEl = document.createElement("option");
            optEl.value = opt; optEl.textContent = opt; input.appendChild(optEl);
          });
        }
      }
      else if (field.type === "Text" || field.type === "Long Text" || field.fieldtype === "Small Text") {
        input = document.createElement("textarea");
        input.className = "form-control"; input.rows = 3;
      }
      else if (field.type === "Check" || field.fieldtype === "Check") {
        input = document.createElement("input"); input.type = "checkbox"; input.style.marginLeft = "8px";
        formGroup.style.display = "flex"; formGroup.style.alignItems = "center";
        input.name = field.fieldname || field.label;
        input.setAttribute("data-dynamic", "true");
        input.setAttribute("data-label", field.label || "");
        input.setAttribute("data-fieldname", field.fieldname || "");
        formGroup.appendChild(input); formGroup.appendChild(label);
        sectionWrapper.appendChild(formGroup); return;
      }
      else if (field.type === "Date" || field.fieldtype === "Date") {
        input = document.createElement("input"); input.type = "date"; input.className = "form-control";
      }
      else {
        input = document.createElement("input"); input.type = "text"; input.className = "form-control";
      }

      if (isRequired) input.required = true;
      input.name = field.fieldname || field.label;
      input.setAttribute("data-dynamic", "true");
      input.setAttribute("data-label", field.label || "");
      input.setAttribute("data-fieldname", field.fieldname || "");

      formGroup.appendChild(label); formGroup.appendChild(input);
      sectionWrapper.appendChild(formGroup);
    });

    const lastField = formWrapper.querySelector(".form-group:last-child");
    if (lastField) lastField.after(sectionWrapper);
    else formWrapper.appendChild(sectionWrapper);
  }

  // ===============================
  // 5️⃣ جمع قيم الحقول الديناميكية
  // ===============================
  function collectDynamicValues() {
    const rows = [];
    document.querySelectorAll('[data-dynamic="true"]').forEach((el) => {
      const field_key = (el.getAttribute("data-fieldname") || "").trim();
      const question = (el.getAttribute("data-label") || el.name || field_key || "").trim();
      let answer;
      if (el.type === "checkbox") answer = el.checked ? 1 : 0;
      else answer = (el.value || "").trim();
      if (el.type !== "checkbox" && (answer === "" || answer === null || typeof answer === "undefined")) return;
      rows.push({ field_key, question, answer });
    });
    return rows;
  }

  // ===============================
  // 6️⃣ توليد نص البحث (نفس منطق Server Script ✨)
  // ===============================
  function generateSearchText(payload) {
    if (!payload || !Array.isArray(payload) || payload.length === 0) return "";
    
    const searchLines = payload.map(function(item) {
      // نفس المنطق: Q: السؤال | A: الإجابة
      const q = item.question || item.label || item.field_key || "";
      const a = item.answer !== undefined ? item.answer : "";
      return "Q: " + q + " | A: " + a;
    });
    
    return searchLines.join("\n"); // دمج الأسطر بفواصل أسطر للبحث
  }

  // ===============================
  // 7️⃣ قبل الحفظ: خزّن JSON + نص البحث
  // ===============================
  frappe.web_form.validate = function () {
    patch_get_values_once();
    const payload = collectDynamicValues();
    const searchText = generateSearchText(payload); // ✅ توليد النص

    // حفظ JSON
    frappe.web_form.doc = frappe.web_form.doc || {};
    frappe.web_form.doc[CFG.JSON_FIELDNAME] = JSON.stringify(payload);
    
    // ✅ حفظ نص البحث في custom_answers_search_index
    frappe.web_form.doc[CFG.SEARCH_FIELDNAME] = searchText;

    console.log("🔍 Search Index:", searchText);
    return true;
  };

  // ===============================
  // 8️⃣ ضمان الإرسال (patch get_values)
  // ===============================
  function patch_get_values_once() {
    if (PATCHED) return;
    if (!window.frappe || !frappe.ui || !frappe.ui.FieldGroup) return;

    const proto = frappe.ui.FieldGroup.prototype;
    if (!proto || typeof proto.get_values !== "function") return;
    const original = proto.get_values;

    proto.get_values = function (allow_incomplete) {
      const values = original.call(this, allow_incomplete);
      if (!values || !frappe.web_form || this !== frappe.web_form) return values;

      try {
        const dyn = collectDynamicValues();
        const json = JSON.stringify(dyn);
        const searchText = generateSearchText(dyn); // ✅ توليد النص

        values[CFG.JSON_FIELDNAME] = json;
        values[CFG.SEARCH_FIELDNAME] = searchText; // ✅ حقن نص البحث

        frappe.web_form.doc = frappe.web_form.doc || {};
        frappe.web_form.doc[CFG.JSON_FIELDNAME] = json;
        frappe.web_form.doc[CFG.SEARCH_FIELDNAME] = searchText;

      } catch (e) { console.warn("Patch error:", e); }
      return values;
    };
    PATCHED = true;
  }
})();

