client_script:
// Load reCAPTCHA script explicitly
frappe.require("https://www.google.com/recaptcha/api.js?onload=onloadCallback&render=explicit&type=api.js");

// Query the element where reCAPTCHA should be rendered
let el = document.querySelector('[data-fieldname="captcha_html_wrapper"]');

// Set initial CAPTCHA state
window.captcha_failed = true;

// Log initial state
console.log("Initial CAPTCHA state:", window.captcha_failed);

// Validate before form submit
frappe.web_form.validate = () => {
    console.log("Validating CAPTCHA...");
    console.log("Current CAPTCHA status:", window.captcha_failed ? "Failed" : "Passed");

    if (window.captcha_failed) {
        console.error("reCAPTCHA not completed!");
        frappe.throw("You need to finish the captcha challenge");
    } else {
        console.log("reCAPTCHA passed. Proceeding with form submission.");
    }
};

// Render reCAPTCHA after page loads
window.onloadCallback = function() {
    console.log("reCAPTCHA is rendering...");

    if (!el) {
        console.error("Could not find element with [data-fieldname='captcha_html_wrapper'] — reCAPTCHA will not render!");
    } else {
        console.log("Found element:", el);
    }

    // Render the widget only if element exists
    if (el) {
        el.innerHTML = '';
        grecaptcha.render(el, {
            'sitekey' : '6LegCWIrAAAAAIYt4KLmr3Ft-UO7FDV2StrPGgVA', 
            'callback': () => {
                window.captcha_failed = false;
                console.log("reCAPTCHA success callback triggered.");
            },
        });
    }
}

